#!/usr/bin/env bash
#
# Upgrade /jobfit/ai-api-key from the CloudFormation-created placeholder
# (a plain String - see processing-stack.yaml for why it can't be a
# SecureString directly) to a real, encrypted SecureString holding your
# actual Gemini API key.
#
# This is a one-time, out-of-band step - deliberately NOT part of
# deploy-infra.sh, so a real secret is never typed into (or generated by)
# a script that also touches version-controlled files.
#
# Usage:
#   GEMINI_API_KEY="..." bash scripts/set-ai-key.sh
#
# After running this, also set USE_LIVE_AI=true on your next
# deploy-infra.sh run to actually start using it - see docs/ai-processing.md.
set -euo pipefail

AWS_REGION="${AWS_REGION:-$(aws configure get region || echo us-east-1)}"
GEMINI_API_KEY="${GEMINI_API_KEY:-}"

if [[ -z "$GEMINI_API_KEY" ]]; then
  echo "ERROR: set GEMINI_API_KEY first, e.g.:" >&2
  echo '  GEMINI_API_KEY="..." bash scripts/set-ai-key.sh' >&2
  exit 1
fi

aws ssm put-parameter \
  --region "$AWS_REGION" \
  --name /jobfit/ai-api-key \
  --type SecureString \
  --value "$GEMINI_API_KEY" \
  --overwrite

echo "==> /jobfit/ai-api-key is now a real SecureString."
echo "==> Next: USE_LIVE_AI=true bash scripts/deploy-infra.sh"
